API Gateway & Routing Layer.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway & Routing Layer container

System_Boundary(api_gateway_container, "API Gateway & Routing Layer") {
    Component(AWS ALB + AWS WAF, "AWS ALB + AWS WAF", "AWS ALB, AWS WAF, TLS 1.3", "Edge routing, TLS 1.3 termination, rate-limiting, DDoS protection, and PCI-DSS PAN masking.")
}

System_Ext(RealTime_Scoring_Engine, "Real-Time Scoring Engine", "AWS ECS Fargate")

Rel(AWS ALB + AWS WAF, RealTime_Scoring_Engine, "Routes authorization payloads for scoring", "gRPC / HTTP2 over AWS VPC private links")

@enduml

Real-Time Scoring Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(real_time_scoring_engine, "Real-Time Scoring Engine") {
    Component(Rule_Evaluation_Component, "Rule Evaluation Component", "Go + expr-lang/expr", "Lightweight evaluation engine for fast in-memory fraud rule execution.")
    Component(ML_Inference_Component, "ML Inference Component", "ONNX Runtime C++ bindings wrapped in Go", "Optimized machine learning inference engine for fast model execution.")
    Component(Decision_Orchestrator_Component, "Decision Orchestrator Component", "Go", "Orchestrates rule evaluation and ML inference to produce the final payment screening decision.")
    Component(Rule_Compiler_Validator_Component, "Rule Compiler & Validator Component", "Go", "Validates and compiles rules before hot-reloading.")
}

Rel(Decision_Orchestrator_Component, Rule_Evaluation_Component, "Evaluates transaction payloads against fraud rules")
Rel(Decision_Orchestrator_Component, ML_Inference_Component, "Invokes model inference for risk scoring")
Rel(Rule_Compiler_Validator_Component, Rule_Evaluation_Component, "Provides compiled and validated rules")

@enduml

Audit & Event Stream.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary("Audit_Event_Stream", "Audit & Event Stream") {
    Component(Event_Ingestion_Router, "Event Ingestion Router", "Amazon EventBridge", "Component routing schema-validated events with Dead Letter Queues to minimize operational overhead.")
    Component(Buffer_Batcher, "Buffer & Batcher", "Amazon Kinesis Data Firehose", "Component aggregating and compressing high-throughput events into Parquet batches.")
}

Rel(Event_Ingestion_Router, Buffer_Batcher, "Forwards filtered events via Kinesis Firehose direct integration over HTTPS.", "HTTPS")

@enduml
